import '../l10n/l10n.dart';
import '../utilities/amount/amount.dart';
import 'isar/models/blockchain_data/transaction_type.dart';
import 'isar/models/blockchain_data/v2/transaction_v2.dart';

/// Kerrigan history categories the filter can select.
enum KerriganTxCategory {
  sent,
  received,
  sentToSelf,
  blockReward,
  masternodeReward,
  masternode,
  shield,
  unshield;

  String get label => switch (this) {
    sent => l10n.txSent,
    received => l10n.txReceived,
    sentToSelf => l10n.txSentToSelf,
    blockReward => l10n.txBlockRewards,
    masternodeReward => l10n.txMasternodeRewards,
    masternode => l10n.txMasternodesAndProposals,
    shield => l10n.txShielded,
    unshield => l10n.txUnshielded,
  };

  /// The categories [tx] belongs to.
  static Set<KerriganTxCategory> allOf(TransactionV2 tx) => {of(tx)};

  static KerriganTxCategory of(TransactionV2 tx) {
    switch (tx.kerriganKind) {
      case KerriganTxKind.blockReward:
        return blockReward;
      case KerriganTxKind.masternodeReward:
        return masternodeReward;
      case KerriganTxKind.burn:
      case KerriganTxKind.masternodeRegistration:
      case KerriganTxKind.masternodeUpdate:
        return masternode;
      case KerriganTxKind.shield:
        return shield;
      case KerriganTxKind.unshield:
        return unshield;
    }
    switch (tx.type) {
      case TransactionType.incoming:
        return received;
      case TransactionType.sentToSelf:
        return sentToSelf;
      default:
        return sent;
    }
  }
}

class TransactionFilter {
  final bool sent;
  final bool received;
  final DateTime? from;
  final DateTime? to;
  final Amount? amount;
  final String keyword;

  /// Kerrigan: categories to show (instead of [sent] / [received]); null when
  /// not filtering by category.
  final Set<KerriganTxCategory>? kerriganCategories;

  TransactionFilter({
    required this.sent,
    required this.received,
    required this.from,
    required this.to,
    required this.amount,
    required this.keyword,
    this.kerriganCategories,
  });

  TransactionFilter copyWith({
    bool? sent,
    bool? received,
    DateTime? from,
    DateTime? to,
    Amount? amount,
    String? keyword,
    Set<KerriganTxCategory>? kerriganCategories,
  }) {
    return TransactionFilter(
      sent: sent ?? this.sent,
      received: received ?? this.received,
      from: from ?? this.from,
      to: to ?? this.to,
      amount: amount ?? this.amount,
      keyword: keyword ?? this.keyword,
      kerriganCategories: kerriganCategories ?? this.kerriganCategories,
    );
  }

  @override
  String toString() {
    return "TxFilter { sent: $sent, received: $received, from: $from, to: $to, amount: $amount, keyword: $keyword, kerriganCategories: $kerriganCategories }";
  }
}
